import{_ as i,c as s,o as t,a3 as o}from"./chunks/framework.CoV49S2T.js";const g=JSON.parse('{"title":"macOS 权限","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/guide/permissions.md","filePath":"zh-CN/guide/permissions.md","lastUpdated":1786595765000}'),e={name:"zh-CN/guide/permissions.md"};function r(n,a,l,c,p,d){return t(),s("div",null,[...a[0]||(a[0]=[o(`<h1 id="macos-权限" tabindex="-1">macOS 权限 <a class="header-anchor" href="#macos-权限" aria-label="Permalink to &quot;macOS 权限&quot;">​</a></h1><p>ClipboardxAI 可能会请求几项 macOS 权限，以带来最佳体验。本页说明每项权限的用途以及如何管理。</p><h2 id="剪贴板-自动化-clipboard-automation" tabindex="-1">剪贴板 / 自动化（Clipboard / Automation） <a class="header-anchor" href="#剪贴板-自动化-clipboard-automation" aria-label="Permalink to &quot;剪贴板 / 自动化（Clipboard / Automation）&quot;">​</a></h2><p>为了在后台捕获剪贴板并将结果粘贴回去，ClipboardxAI 使用 macOS 的自动化（Automation）访问。</p><p><strong>用途</strong>：在你复制时读取当前粘贴板，并在你运行操作时将结果写回。</p><p><strong>管理方式</strong>：<strong>系统设置 → 隐私与安全性 → 自动化（System Settings → Privacy &amp; Security → Automation）</strong> → 启用 <strong>ClipboardxAI</strong>。</p><p>在首次启动时按提示授予访问权限。你可以随时管理或撤销该权限。</p><h2 id="辅助功能-可选-accessibility" tabindex="-1">辅助功能（可选，Accessibility） <a class="header-anchor" href="#辅助功能-可选-accessibility" aria-label="Permalink to &quot;辅助功能（可选，Accessibility）&quot;">​</a></h2><p>部分版本使用辅助功能（Accessibility）来提供全局键盘快捷键，并从任意位置唤出历史面板。</p><p><strong>用途</strong>：打开历史面板并通过快捷键运行操作，即使应用当前未聚焦。</p><p><strong>管理方式</strong>：<strong>系统设置 → 隐私与安全性 → 辅助功能（System Settings → Privacy &amp; Security → Accessibility）</strong> → 启用 <strong>ClipboardxAI</strong>。</p><h2 id="通知-可选-notifications" tabindex="-1">通知（可选，Notifications） <a class="header-anchor" href="#通知-可选-notifications" aria-label="Permalink to &quot;通知（可选，Notifications）&quot;">​</a></h2><p>当某项长时间运行的操作完成或需要关注时，ClipboardxAI 可能会显示通知。</p><p><strong>用途</strong>：在操作完成或需要配置时提醒你。</p><p><strong>管理方式</strong>：<strong>系统设置 → 通知（System Settings → Notifications）</strong> → <strong>ClipboardxAI</strong>。</p><h2 id="完全磁盘访问-可选-full-disk-access" tabindex="-1">完全磁盘访问（可选，Full Disk Access） <a class="header-anchor" href="#完全磁盘访问-可选-full-disk-access" aria-label="Permalink to &quot;完全磁盘访问（可选，Full Disk Access）&quot;">​</a></h2><p>正常使用无需此项。仅当你希望应用读取系统受保护位置的剪贴内容时才需要。</p><p><strong>管理方式</strong>：<strong>系统设置 → 隐私与安全性 → 完全磁盘访问（System Settings → Privacy &amp; Security → Full Disk Access）</strong>。</p><p>该权限为可选项，仅在高级场景才需要。</p><h2 id="使用终端重置权限" tabindex="-1">使用终端重置权限 <a class="header-anchor" href="#使用终端重置权限" aria-label="Permalink to &quot;使用终端重置权限&quot;">​</a></h2><p>如果权限对话框被关闭或状态不一致，你可以使用 <code>tccutil</code> 重置 macOS 的权限提示：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 为 ClipboardxAI 重置自动化 / 辅助功能提示</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tccutil</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> All</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> com.w3cub.clipboard</span></span></code></pre></div><p>运行 <code>tccutil</code> 后，请重启应用并再次触发该功能以重新弹出提示。</p><h2 id="故障排除" tabindex="-1">故障排除 <a class="header-anchor" href="#故障排除" aria-label="Permalink to &quot;故障排除&quot;">​</a></h2><ul><li>如果剪贴板历史未捕获复制内容，请检查是否已授予 <strong>自动化（Automation）</strong> 权限。</li><li>如果全局快捷键无效，请检查 <strong>辅助功能（Accessibility）</strong> 权限。</li><li>更改权限后，务必退出并重新打开 ClipboardxAI，更改才会生效。</li></ul><p>如需更多帮助，请访问<a href="/zh-CN/guide/troubleshooting.html">故障排除指南</a>。</p>`,26)])])}const u=i(e,[["render",r]]);export{g as __pageData,u as default};
